function toIn(cm){ return cm/2.54; }
function ibw(formula, sex, cm){
  var inch=toIn(cm)-60; // 超过 5 英尺(60in)的部分
  var m = sex==='m';
  if(formula==='devine')   return m ? 50 + 2.3*inch : 45.5 + 2.3*inch;
  if(formula==='hamwi')    return m ? 48 + 2.7*inch : 45.5 + 2.2*inch;
  if(formula==='robinson') return m ? 52 + 1.9*inch : 49   + 1.7*inch;
  if(formula==='miller')   return m ? 56.2 + 1.41*inch : 53.1 + 1.36*inch;
  return null;
}
function ibwAll(sex, cm){ return {devine:ibw('devine',sex,cm), hamwi:ibw('hamwi',sex,cm),
  robinson:ibw('robinson',sex,cm), miller:ibw('miller',sex,cm)}; }
function healthyRange(cm){ var m=cm/100; return {lo:18.5*m*m, hi:24.9*m*m}; }
var EXPORTS={toIn:toIn, ibw:ibw, ibwAll:ibwAll, healthyRange:healthyRange};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.IdealWeightForgePure = EXPORTS; }
